/* Mobile reading containers.
 * Keep all content in the document and let long sections scroll naturally on
 * small screens instead of hiding items behind "Show all" controls.
 */
(function () {
  'use strict';
  if (!document.body.classList.contains('about-page')) return;
  const selectors = [
    '.news',
    '.logo-row--research',
    '.teaching-section',
    '.publications-grouped',
  ];

  document.querySelectorAll(selectors.join(',')).forEach((container) => {
    container.classList.add('mobile-scroll-container');
  });

  // Remove controls generated by an older cached script, if any are present.
  document.querySelectorAll('.mobile-disclosure').forEach((button) => button.remove());
})();
